// Taken before every capacity decision, so two requests cannot both take
// the last free RAM or disk.
func (q *Queries) LockHost(ctx context.Context, id uuid.UUID) (Host, error) {
	row := q.db.QueryRow(ctx, lockHost, id)
	var i Host
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.AgentUrl,
		&i.PublicUrl,
		&i.AgentTokenEnc,
		&i.StreamSecretEnc,
		&i.AdminState,
		&i.TotalRamMb,
		&i.TotalVcpus,
		&i.TotalDiskGb,
		&i.FreeDiskGb,
		&i.ReservedRamMb,
		&i.CpuOvercommit,
		&i.Images,
		&i.AgentVersion,
		&i.LastHeartbeatAt,
		&i.CreatedAt,
	)
	return i, err
}

