const openUsageInterval = `-- name: OpenUsageInterval :exec
INSERT INTO usage_intervals (vm_id, user_id, host_id, ram_mb, vcpus, started_at)
VALUES ($1, $2, $3, $4, $5, now())
ON CONFLICT (vm_id) WHERE ended_at IS NULL DO NOTHING
`

type OpenUsageIntervalParams struct {
	VmID   uuid.UUID
	UserID uuid.UUID
	HostID uuid.UUID
	RamMb  int32
	Vcpus  int32
}

// At most one open interval per VM: opening twice is harmless.
func (q *Queries) OpenUsageInterval(ctx context.Context, arg OpenUsageIntervalParams) error {
	_, err := q.db.Exec(ctx, openUsageInterval,
		arg.VmID,
		arg.UserID,
		arg.HostID,
		arg.RamMb,
		arg.Vcpus,
	)
	return err
}

