const userVMTotals = `-- name: UserVMTotals :one
SELECT count(*)::int AS vm_count,
       COALESCE(sum(ram_mb), 0)::int AS ram_mb,
       COALESCE(sum(vcpus), 0)::int AS vcpus,
       COALESCE(sum(disk_gb), 0)::int AS disk_gb
FROM vms
WHERE user_id = $1 AND deleted_at IS NULL
`

type UserVMTotalsRow struct {
	VmCount int32
	RamMb   int32
	Vcpus   int32
	DiskGb  int32
}

// What a user's VMs add up to, for the per-user limits.
func (q *Queries) UserVMTotals(ctx context.Context, userID uuid.UUID) (UserVMTotalsRow, error) {
	row := q.db.QueryRow(ctx, userVMTotals, userID)
	var i UserVMTotalsRow
	err := row.Scan(
		&i.VmCount,
		&i.RamMb,
		&i.Vcpus,
		&i.DiskGb,
	)
	return i, err
}
